// 视频导出分辨率预设的纯计算: 只给高度, 宽度由舞台宽高比推导。

/**
 * 由预设高度与舞台宽高比推导输出宽度。
 *
 * 与 Rust 侧 `webgal_video_export::api::output_width` 保持一致: 四舍五入后取偶数,
 * 因为 H.264 的 yuv420p 不接受奇数宽度。
 */
export function presetWidth(height: number, stageWidth: number, stageHeight: number): number {
  if (!Number.isFinite(height) || !Number.isFinite(stageWidth) || !Number.isFinite(stageHeight)) {
    return 0;
  }
  const raw = Math.round((height * stageWidth) / Math.max(1, stageHeight));
  return raw % 2 === 0 ? raw : raw - 1;
}

/** 对话框里的五档高度。 */
export const RESOLUTION_HEIGHTS = [480, 720, 1080, 1440, 2160] as const;

/** 生成 `720p（1280 × 720）` 这样的选项标签。 */
export function resolutionOptions(stageWidth: number, stageHeight: number): Array<{ value: string; label: string }> {
  return RESOLUTION_HEIGHTS.map((height) => ({
    value: String(height),
    label: `${height}p（${presetWidth(height, stageWidth, stageHeight)} × ${height}）`,
  }));
}
